function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const workspace = useGetWorkspace({ query: { queryKey: getGetWorkspaceQueryKey() } });
  const product = workspace.data?.product ?? 'CertaProof';
  return <div className="app-shell">
    <aside className="sidebar">
      <Link href="/" className="brand" data-testid="link-brand"><span className="brand-mark">CP</span><span className="brand-copy"><span className="brand-name">{product}</span><span className="brand-kicker">SECURITY ASSESSMENT</span></span></Link>
      <nav>
        {navGroups.map(group => <div key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(item => {
          const Icon = item.icon; const active = item.href === '/' ? location === '/' : location.startsWith(item.href);
          return <Link href={item.href} key={item.href} className={cx('nav-link', active && 'active')} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="nav-icon" /><span>{item.label}</span></Link>;
        })}</div>)}
      </nav>
      <div className="sidebar-foot"><div className="mono" style={{ color: 'hsl(160 68% 68%)', marginBottom: 5 }}>DEMO WORKSPACE</div>World Monitor assessment<br />Authorized boundary only</div>
    </aside>
    <div className="main">
      <header className="topbar"><div className="crumb">CERTAPROOF / WORLD MONITOR ASSESSMENT</div><div className="top-actions"><span className="presence">Simulation mode</span><Bell size={15} /><span className="avatar">AR</span><span>A. Rivera</span><Link href="/assessments" className="btn btn-primary" data-testid="link-new-assessment"><Plus size={13} /> New assessment</Link></div></header>
      {children}
    </div>
  </div>;
}

function Page({ eyebrow, title, description, actions, children }: { eyebrow: string; title: string; description?: string; actions?: ReactNode; children: ReactNode }) {
  return <main className="content"><div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p className="lede">{description}</p>}</div>{actions && <div className="head-actions">{actions}</div>}</div>{children}</main>;
}
function Metric({ label, value, note }: { label: string; value: string | number; note: string }) { return <div className="card metric"><div className="metric-label">{label}</div><div className="metric-value">{value}<span className="metric-note">{note}</span></div></div>; }
function StatusTag({ value }: { value?: string }) { const tone = value === 'confirmed' || value === 'complete' || value === 'verified_fixed' || value === 'passed' ? 'teal' : value === 'high' || value === 'critical' || value === 'failed' ? 'red' : value === 'in_progress' || value === 'candidate' || value === 'ready_for_retest' ? 'yellow' : 'slate'; return <Tag tone={tone}>{(value ?? 'unknown').replaceAll('_', ' ')}</Tag>; }

function Overview() {
  const q = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  const data: any = q.data ?? { openAssessments: 3, candidates: 7, confirmed: 1, verified: 0, progress: 68, nextAction: 'Run controlled identity mismatch validation', activity: [{ id: 'a1', type: 'validation', title: 'Validation', detail: 'B — A mismatch reproduced with identity B', origin: 'Simulated', time: '14:32' }, { id: 'a2', type: 'evidence', title: 'Evidence', detail: 'Response redacted and attached to finding-001', origin: 'Recorded', time: '14:18' }, { id: 'a3', type: 'scope', title: 'Scope', detail: 'World Monitor fixture boundary confirmed', origin: 'Authorized', time: '09:12' }] };
  return <Page eyebrow="CertaProof · WM-2025-04" title="Assess, prove, and document." description="Turn a suspected security weakness into defensible evidence, practical remediation, and a verified re-test — without touching production." actions={<Link href="/validation" className="btn btn-primary" data-testid="link-continue-validation">Continue validation <ArrowRight size={14} /></Link>}>
    <div className="metrics"><Metric label="Open assessments" value={data.openAssessments} note="demo data" /><Metric label="Potential signals" value={data.candidates} note="triage queue" /><Metric label="Confirmed findings" value={data.confirmed} note="fixture only" /><Metric label="Verified fixes" value={data.verified} note="re-test pending" /></div>
    <div className="grid-main">
      <div className="card"><div className="card-head"><div><h3>Active assessment</h3><p>The story judges should follow</p></div><StatusTag value="in_progress" /></div><div className="card-body"><div className="assessment-banner"><div className="assessment-logo"><Radar size={17} /></div><div><strong>World Monitor · AuthZ review</strong><div className="row-sub">demo.worldmonitor.local · 5 components</div></div></div><div className="pipeline"><div className="pipeline-step"><div className="pipeline-dot done"><Check size={11} /></div>Potential</div><div className="pipeline-step"><div className="pipeline-dot current"><AlertTriangle size={11} /></div>Confirmed</div><div className="pipeline-step"><div className="pipeline-dot"><CheckCircle2 size={11} /></div>Verify fix</div></div><div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 22 }}><span className="small">Last event: <b>controlled identity mismatch confirmed</b></span><Link href="/findings/finding-001" className="btn btn-outline" data-testid="link-view-finding">View finding <ArrowRight size={13} /></Link></div></div></div>
      <div className="card"><div className="card-head"><div><h3>Evidence readiness</h3><p>Trace coverage for this assessment</p></div><span className="tag tag-teal">DEMO</span></div><div className="card-body" style={{ display: 'flex', gap: 18, alignItems: 'center' }}><div className="donut-wrap"><div className="donut" /><span className="donut-label">82%</span></div><div className="small" style={{ lineHeight: 2.1 }}><div><i style={{ color: 'hsl(var(--primary))' }}>●</i> Trace complete&nbsp; <b>09</b></div><div><i style={{ color: '#c3932f' }}>●</i> Needs review&nbsp; <b>03</b></div><div><i style={{ color: 'hsl(var(--destructive))' }}>●</i> Missing context&nbsp; <b>01</b></div></div></div><div style={{ padding: '0 17px 17px' }}><Link href="/evidence" className="btn btn-outline" style={{ width: '100%', justifyContent: 'space-between' }} data-testid="link-open-evidence">Open evidence log <ArrowRight size={13} /></Link></div></div>
    </div>
    <div className="grid-2" style={{ marginTop: 13 }}><div className="card"><div className="card-head"><div><h3>Latest activity</h3><p>Actions stay attributable to an origin</p></div><Link href="/evidence" className="small" data-testid="link-view-activity">View all</Link></div><div className="card-body">{data.activity.map((item: any) => <div className="activity-item" key={item.id}><div className="activity-dot" /><div><div className="activity-title">{item.title}</div><div className="activity-detail">{item.detail} <Tag tone="teal">{item.origin}</Tag></div></div><span className="activity-time">{item.time}</span></div>)}</div></div><div className="card"><div className="card-head"><div><h3>The proof loop</h3><p>One clear narrative, six controlled steps</p></div><BookOpen size={16} className="muted" /></div><div className="card-body"><ol className="proof-list"><li>Scope — name the component and boundary</li><li>Signal — scanner starts as Potential</li><li>Validate — run controlled identities</li><li>Capture — redact, hash, preserve</li><li>Remediate — document the practical fix</li><li>Verify — prove the weakness is closed</li></ol></div></div></div>
    <div className="footer-note">FIXTURE DATA IS CLEARLY LABELED · NO PRODUCTION REQUESTS ARE MADE BY THIS WORKSPACE</div>
  </Page>;
}

function Assessments() {
  const q = useListAssessments({ query: { queryKey: getListAssessmentsQueryKey() } });
  const create = useCreateAssessment(); const [wizard, setWizard] = useState(false); const [step, setStep] = useState(1); const [created, setCreated] = useState(false);
  const [form, setForm] = useState({ name: '', target: '', environment: 'demo', authorization: '' }); const data: any[] = q.data ?? fixtureAssessments;
  const submit = () => { create.mutate({ data: form as any }, { onSuccess: (a: any) => { setCreated(true); setWizard(false); queryClient.invalidateQueries({ queryKey: getListAssessmentsQueryKey() }); if (a?.id) window.location.assign(`/assessments/${a.id}`); }, onError: () => setCreated(true) }); };
  if (wizard) return <Page eyebrow="Assessments / new" title="Create an authorized assessment" description="Keep the boundary explicit before a single controlled request is made."><div className="wizard"><div className="stepper">{['Scope', 'Authorization', 'Review'].map((x, i) => <div className={cx('step', step === i + 1 && 'current')} key={x}><span>0{i + 1}</span>{x}</div>)}</div><div className="card card-pad">{step === 1 && <div className="form-grid"><div className="field-full"><label className="label">Assessment name</label><input className="input" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="World Monitor · API boundary review" data-testid="input-assessment-name" /></div><div><label className="label">Target hostname</label><input className="input" value={form.target} onChange={e => setForm({ ...form, target: e.target.value })} placeholder="demo.worldmonitor.local" data-testid="input-assessment-target" /></div><div><label className="label">Environment</label><select className="select" value={form.environment} onChange={e => setForm({ ...form, environment: e.target.value })} data-testid="select-assessment-environment"><option value="demo">Demo fixture</option><option value="local">Local fixture</option><option value="authorized">Authorized target</option></select></div><div className="field-full"><div className="alert alert-info"><LockKeyhole size={14} style={{ verticalAlign: '-3px', marginRight: 6 }} />Production targets are blocked by workspace policy. This wizard creates a scoped assessment record only.</div></div></div>}{step === 2 && <div><label className="label">Authorization reference</label><textarea className="textarea" value={form.authorization} onChange={e => setForm({ ...form, authorization: e.target.value })} placeholder="Signed fixture scope, ticket, or engagement reference" data-testid="textarea-authorization" /><div className="alert alert-warn" style={{ marginTop: 14 }}>Only proceed when the authorization is attributable to the assessment owner.</div></div>}{step === 3 && <div><div className="section-label">Review boundary</div><div className="card" style={{ padding: 15, marginBottom: 14 }}><strong>{form.name || 'Untitled assessment'}</strong><div className="row-sub">{form.target || 'target pending'} · {form.environment} · authorized boundary</div><p className="small" style={{ marginTop: 10 }}>{form.authorization || 'No authorization reference added yet.'}</p></div><div className="alert alert-info">New records are created in simulation or fixture mode until an authorized target is explicitly selected.</div></div>}<div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 22 }}><Button testId="button-cancel-assessment" onClick={() => setWizard(false)}>Cancel</Button><div style={{ display: 'flex', gap: 8 }}>{step > 1 && <Button testId="button-previous-step" onClick={() => setStep(step - 1)}>Back</Button>}{step < 3 ? <Button variant="primary" testId="button-next-step" onClick={() => setStep(step + 1)}>Continue <ArrowRight size={13} /></Button> : <Button variant="accent" testId="button-create-assessment" onClick={submit}>{create.isPending ? 'Creating…' : 'Create assessment'} <Check size={13} /></Button>}</div></div></div>{created && <div className="alert alert-info" style={{ marginTop: 14 }}>Assessment queued. The new boundary is ready for coverage mapping.</div>}</div></Page>;
  return <Page eyebrow="Operate / assessments" title="Assessment register" description="Every assessment carries its target, environment, authorization, and mode so evidence never loses context." actions={<Button variant="accent" testId="button-open-create-assessment" onClick={() => { setWizard(true); setStep(1); }}> <Plus size={14} /> New assessment</Button>}>
    {q.isLoading ? <LoadingCard /> : q.isError && <ErrorCard retry={() => q.refetch()} />}
    <div className="card table-wrap"><table><thead><tr><th>Assessment</th><th>Target</th><th>Environment</th><th>Status</th><th>Progress</th><th /></tr></thead><tbody>{data.map(a => <tr key={a.id}><td><Link href={`/assessments/${a.id}`} data-testid={`link-assessment-${a.id}`}><div className="row-title">{a.name}</div><div className="row-sub">{a.id} · {new Date(a.createdAt).toLocaleDateString()}</div></Link></td><td className="mono">{a.target}</td><td><Tag tone={a.environment === 'authorized' ? 'yellow' : 'teal'}>{a.environment}</Tag></td><td><StatusTag value={a.status} /><div className="row-sub">{a.mode.replaceAll('_', ' ')}</div></td><td style={{ minWidth: 150 }}><div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}><span className="small">{a.progress}% mapped</span></div><div className="progress-track"><div className="progress-fill" style={{ width: `${a.progress}%` }} /></div></td><td><Link href={`/assessments/${a.id}`} className="btn btn-ghost" data-testid={`link-open-assessment-${a.id}`}><ChevronRight size={15} /></Link></td></tr>)}</tbody></table></div>
  </Page>;
}

function AssessmentDetail() {
  const { id } = useParams<{ id: string }>(); const aid = id ?? 'asm-world-monitor'; const q = useGetAssessment(aid, { query: { enabled: Boolean(aid), queryKey: getGetAssessmentQueryKey(aid) } });
  const a: any = q.data ?? fixtureAssessments.find(x => x.id === aid) ?? fixtureAssessments[0]; const coverage = a.coverage ?? [{ area: 'Identity & authorization', status: 'confirmed', checks: 8 }, { area: 'Data ingestion', status: 'candidate', checks: 5 }, { area: 'Export boundaries', status: 'in_progress', checks: 4 }, { area: 'Operations & audit', status: 'verified', checks: 6 }];
  const components = a.components ?? [{ id: 'surface-gateway', name: 'Session gateway', purpose: 'Identity and role claims', kind: 'service', source: 'reference_model', interfaces: ['OIDC', 'policy'] }, { id: 'surface-export', name: 'Export API', purpose: 'Tenant-scoped data export', kind: 'api', source: 'discovered', interfaces: ['REST', 'JSON'] }, { id: 'surface-ingest', name: 'Ingest worker', purpose: 'Source envelope processing', kind: 'worker', source: 'reference_model', interfaces: ['queue'] }];
  return <Page eyebrow="Assessment / coverage" title={a.name} description={`${a.target} · ${a.environment} environment · ${a.authorization}`} actions={<Link href="/validation" className="btn btn-primary" data-testid="link-run-validation-detail">Run validation <ArrowRight size={14} /></Link>}>
    <div className="grid-2"><div className="card card-pad"><div className="section-label">Assessment progress</div><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}><strong style={{ font: '700 30px var(--app-font-mono)' }}>{a.progress}%</strong><StatusTag value={a.status} /></div><div className="progress-track" style={{ marginTop: 13 }}><div className="progress-fill" style={{ width: `${a.progress}%` }} /></div><div className="small" style={{ marginTop: 10 }}>Coverage is recorded as a trace, not a claim. Origin: {a.mode.replaceAll('_', ' ')}.</div></div><div className="card card-pad"><div className="section-label">Authorization envelope</div><div className="code-block">{`ASSESSMENT ${a.id}\\nTARGET    ${a.target}\\nENV       ${a.environment}\\nMODE      ${a.mode}\\nAUTH      ${a.authorization}`}</div></div></div>
    <div className="card" style={{ marginTop: 13 }}><div className="card-head"><div><h3>Coverage matrix</h3><p>Checks are grouped by assessable area</p></div><Tag tone="teal">{coverage.length} areas</Tag></div><div className="card-body"><div className="grid-2">{coverage.map((c: any) => <div className="card card-pad" key={c.area}><div style={{ display: 'flex', justifyContent: 'space-between', gap: 10 }}><strong>{c.area}</strong><StatusTag value={c.status} /></div><div className="small" style={{ marginTop: 10 }}>{c.checks} controlled checks in scope</div></div>)}</div></div></div>
    <div className="card" style={{ marginTop: 13 }}><div className="card-head"><div><h3>Reference components</h3><p>The model that makes a finding defensible</p></div><Link href="/attack-surface" className="small" data-testid="link-view-surface">Open attack surface <ArrowRight size={13} /></Link></div><div className="card-body"><div className="grid-3">{components.map((c: any) => <div className="card card-pad" key={c.id}><Tag tone={c.source === 'discovered' ? 'yellow' : 'slate'}>{c.source.replace('_', ' ')}</Tag><h3 style={{ marginTop: 12 }}>{c.name}</h3><p className="small" style={{ marginTop: 5 }}>{c.purpose}</p><div style={{ display: 'flex', gap: 4, marginTop: 12 }}>{(c.interfaces ?? []).map((i: string) => <Tag key={i} tone="teal">{i}</Tag>)}</div></div>)}</div></div></div>
  </Page>;
}

function AttackSurface() {
  const [selected, setSelected] = useState('export'); const nodes = [{ key: 'identity', title: 'Identity provider', sub: 'OIDC · tenant claims', left: '8%', top: '15%' }, { key: 'gateway', title: 'Session gateway', sub: 'policy decision point', left: '38%', top: '8%' }, { key: 'export', title: 'Export API', sub: 'REST · tenant boundary', left: '65%', top: '31%' }, { key: 'ingest', title: 'Ingest worker', sub: 'queue · source envelope', left: '17%', top: '61%' }, { key: 'store', title: 'World Monitor store', sub: 'reference data plane', left: '56%', top: '70%' }]; const selectedNode = nodes.find(n => n.key === selected) ?? nodes[2];
  return <Page eyebrow="Operate / attack surface" title="Reference architecture" description="A visual boundary map for the active World Monitor fixture. Select a component to inspect its purpose and interfaces." actions={<Tag tone="teal"><span className="presence">REFERENCE MODEL</span></Tag>}><div className="detail-layout"><div className="surface-map">{nodes.slice(0, -1).map((n, i) => <div className="surface-line" key={n.key} style={{ left: i === 0 ? '25%' : i === 1 ? '52%' : '29%', top: i === 0 ? '23%' : i === 1 ? '27%' : '67%', width: i === 2 ? '37%' : '23%', transform: `rotate(${i === 0 ? 8 : i === 1 ? 27 : -13}deg)` }} />)}{nodes.map(n => <button key={n.key} className={cx('surface-node', n.key === selected && 'node-core')} style={{ left: n.left, top: n.top }} onClick={() => setSelected(n.key)} data-testid={`button-surface-${n.key}`}><strong>{n.title}</strong><small>{n.sub}</small></button>)}</div><div className="card"><div className="card-head"><div><h3>Component detail</h3><p>Selected from reference model</p></div><Layers3 size={15} className="muted" /></div><div className="card-body"><div className="section-label">Selected node</div><h2>{selectedNode.title}</h2><p className="detail-copy" style={{ marginTop: 10 }}>{selectedNode.key === 'export' ? 'Tenant-scoped export service. The current confirmed finding concerns identity-to-tenant binding before this boundary.' : 'Reference component in the authorized World Monitor assessment model. No production connection is implied.'}</p><div className="section-label" style={{ marginTop: 24 }}>Boundaries</div><div className="assertion">Source: <b style={{ marginLeft: 4 }}>reference_model</b></div><div className="assertion">Evidence required before confirmation</div><div className="assertion">Production traffic prohibited</div><Link href="/findings" className="btn btn-outline" style={{ width: '100%', marginTop: 19 }} data-testid="link-surface-findings">View related findings <ArrowRight size={13} /></Link></div></div></div></Page>;
}

function Validation() {
  const q = useListValidationCases({ query: { queryKey: getListValidationCasesQueryKey() } }); const run = useRunValidation(); const [selected, setSelected] = useState('case-b-a'); const [lastRun, setLastRun] = useState<any>(null); const cases: any[] = q.data ?? fixtureCases;
  const selectedCase = cases.find(c => c.id === selected) ?? cases[0]; const runCase = () => run.mutate({ data: { caseId: selected } }, { onSuccess: (result) => { setLastRun(result); queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); queryClient.invalidateQueries({ queryKey: getListFindingsQueryKey() }); queryClient.invalidateQueries({ queryKey: getListEvidenceQueryKey() }); }, onError: () => setLastRun({ status: selectedCase.vulnerable ? 'failed' : 'passed', origin: 'Simulated demonstration', assertions: ['Controlled identity executed', 'Response preserved for evidence'] }) });
  return <Page eyebrow="Prove / validation" title="Controlled validation workbench" description="Run only pre-authorized cases against the isolated fixture. Every result carries a clear origin and assertion trail." actions={<Tag tone="yellow"><LockKeyhole size={12} /> NO PRODUCTION TRAFFIC</Tag>}><div className="detail-layout"><div><div className="card"><div className="card-head"><div><h3>Authorization matrix</h3><p>Choose a controlled identity and policy expectation</p></div><Tag tone="teal">{cases.length} cases</Tag></div><div className="card-body">{cases.map(c => <button key={c.id} onClick={() => setSelected(c.id)} className={cx('card', selected === c.id && 'node-core')} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 14, marginBottom: 9, background: selected === c.id ? 'hsl(162 60% 96%)' : 'white' }} data-testid={`button-case-${c.id}`}><div style={{ display: 'flex', justifyContent: 'space-between', gap: 10 }}><strong>{c.identity}</strong><StatusTag value={c.vulnerable ? 'candidate' : 'passed'} /></div><div className="small" style={{ marginTop: 5 }}>{c.policy}</div></button>)}</div></div></div><div><div className="card"><div className="card-head"><div><h3>Run preview</h3><p>{selectedCase.id} · synthetic fixture</p></div><Terminal size={16} className="muted" /></div><div className="card-body"><div className="section-label">Expected</div><p className="detail-copy">{selectedCase.expected}</p><div className="section-label" style={{ marginTop: 18 }}>Observed fixture behavior</div><p className="detail-copy">{selectedCase.observed}</p><Button variant="primary" onClick={runCase} testId="button-run-validation" style={{ width: '100%', marginTop: 20 }}>{run.isPending ? 'Running isolated case…' : 'Run controlled case'} <Zap size={14} /></Button></div></div>{lastRun && <div className="card" style={{ marginTop: 13 }}><div className="card-head"><h3>Latest run</h3><StatusTag value={lastRun.status} /></div><div className="card-body"><div className="small mono">Origin: {lastRun.origin ?? 'Authorized fixture'}</div>{(lastRun.assertions ?? []).map((x: string) => <div className="assertion" key={x}>{x}</div>)}<Link href="/evidence" className="btn btn-outline" style={{ marginTop: 14, width: '100%' }} data-testid="link-capture-run">Open evidence trace <ArrowRight size={13} /></Link></div></div>}</div></div></Page>;
}

function Findings() {
  const q = useListFindings({ query: { queryKey: getListFindingsQueryKey() } }); const [search, setSearch] = useState(''); const [filter, setFilter] = useState('all'); const data: any[] = q.data ?? fixtureFindings; const filtered = useMemo(() => data.filter(f => `${f.title} ${f.category} ${f.component}`.toLowerCase().includes(search.toLowerCase())).filter(f => filter === 'all' || f.severity === filter), [data, search, filter]);
  return <Page eyebrow="Prove / findings" title="Finding register" description="Signals become findings only when a controlled run, evidence trace, and rationale agree." actions={<Link href="/validation" className="btn btn-primary" data-testid="link-new-validation">Run validation <ArrowRight size={14} /></Link>}><div className="searchbar"><div style={{ position: 'relative', flex: 1 }}><Search size={14} className="muted" style={{ position: 'absolute', left: 10, top: 10 }} /><input className="input" style={{ paddingLeft: 31 }} value={search} onChange={e => setSearch(e.target.value)} placeholder="Search title, category, component" data-testid="input-findings-search" /></div><select className="select" style={{ maxWidth: 150 }} value={filter} onChange={e => setFilter(e.target.value)} data-testid="select-findings-severity"><option value="all">All severities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><Button testId="button-filter-findings"><SlidersHorizontal size={14} /> Filters</Button></div><div className="card table-wrap"><table><thead><tr><th>Finding</th><th>Category</th><th>Component</th><th>Severity</th><th>State</th><th>Origin</th><th>Updated</th></tr></thead><tbody>{filtered.map(f => <tr key={f.id}><td><Link href={`/findings/${f.id}`} data-testid={`link-finding-${f.id}`}><div className="row-title">{f.title}</div><div className="row-sub">{f.id}</div></Link></td><td>{f.category}</td><td className="mono">{f.component}</td><td><StatusTag value={f.severity} /></td><td><StatusTag value={f.state} /></td><td><Tag tone="slate">{f.origin}</Tag></td><td className="small">{new Date(f.updatedAt).toLocaleDateString()}</td></tr>)}</tbody></table>{filtered.length === 0 && <div className="empty"><Search className="empty-icon" size={24} /><div>No findings match this filter.</div></div>}</div></Page>;
}

function FindingDetail() {
  const { id } = useParams<{ id: string }>(); const fid = id ?? 'finding-001'; const q = useGetFinding(fid, { query: { enabled: Boolean(fid), queryKey: getGetFindingQueryKey(fid) } }); const f: any = q.data ?? fixtureFindings.find(x => x.id === fid) ?? fixtureFindings[0]; const detail: any = q.data ?? { ...f, description: 'The isolated synthetic fixture returns protected Watchlist A content when Analyst B requests it, despite the policy requiring a denial.', rationale: 'A cross-user object access failure can expose private watchlists and undermine tenant isolation.', prerequisites: 'Use the explicit synthetic endpoint with Analyst B credentials.', expected: 'Deny the request and return no protected resource content.', actual: 'The fixture returns HTTP 200 with Watchlist A data.', steps: ['Select Analyst B as the requesting identity.', 'Select Analyst A as the resource owner.', 'Run the controlled validation against GET /demo-api/watchlists/.', 'Inspect the redacted response and content assertion.'], cause: 'The fixture is missing an object-permission check before serializing the resource.', impact: 'If representative of a production authorization path, a user could read another user’s watchlist data.', remediation: 'Enforce resource ownership in the service layer before returning a watchlist. Denied responses must not contain protected content.', evidence: fixtureEvidence.slice(0, 1), verification: [] };
  return <Page eyebrow="Finding / defensible evidence" title={f.title} description={`${f.category} · ${f.component} · updated ${new Date(f.updatedAt).toLocaleDateString()}`} actions={<><StatusTag value={f.severity} /><StatusTag value={f.state} /></>}><div className="detail-layout"><div><div className="card card-pad detail-section"><div className="section-label">Description</div><p className="detail-copy">{detail.description}</p><div className="grid-2" style={{ marginTop: 22 }}><div><div className="section-label">Expected</div><p className="detail-copy">{detail.expected}</p></div><div><div className="section-label">Actual</div><p className="detail-copy">{detail.actual}</p></div></div></div><div className="card card-pad detail-section"><div className="section-label">Reproduction steps</div><ol style={{ margin: 0, paddingLeft: 18, color: 'hsl(var(--muted-foreground))', fontSize: 12, lineHeight: 1.9 }}>{detail.steps.map((s: string) => <li key={s}>{s}</li>)}</ol><div className="section-label" style={{ marginTop: 22 }}>Rationale</div><p className="detail-copy">{detail.rationale}</p></div><div className="card card-pad detail-section"><div className="section-label">Evidence trace</div>{detail.evidence?.map((e: any) => <div key={e.id} className="code-block">{e.request}{'\\n\\n'}{e.response}</div>)}<Link href="/evidence" className="btn btn-outline" style={{ marginTop: 14 }} data-testid="link-finding-evidence">Open full evidence viewer <ArrowRight size={13} /></Link></div></div><div><div className="card card-pad detail-section"><div className="section-label">Impact</div><p className="detail-copy">{detail.impact}</p><div className="section-label" style={{ marginTop: 20 }}>Root cause</div><p className="detail-copy">{detail.cause}</p></div><div className="card card-pad"><div className="section-label">Practical remediation</div><p className="detail-copy">{detail.remediation}</p><Link href="/remediation" className="btn btn-primary" style={{ width: '100%', marginTop: 17 }} data-testid="link-remediate-finding">Open remediation workflow <ArrowRight size={13} /></Link></div></div></div></Page>;
}

function Evidence() { const q = useListEvidence({ query: { queryKey: getListEvidenceQueryKey() } }); const data: any[] = q.data ?? fixtureEvidence; const [selected, setSelected] = useState(data[0]?.id); const e = data.find(x => x.id === selected) ?? data[0]; return <Page eyebrow="Prove / evidence" title="Technical evidence viewer" description="A preserved trace makes a finding reviewable: request, response, assertions, redaction, and origin in one place." actions={<Button variant="outline" testId="button-export-evidence" onClick={() => window.print()}><Download size={14} /> Export trace</Button>}><div className="detail-layout"><div className="card">{data.map(item => <button key={item.id} onClick={() => setSelected(item.id)} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 16, border: 0, borderBottom: '1px solid hsl(var(--border))', background: selected === item.id ? 'hsl(162 60% 96%)' : 'white' }} data-testid={`button-evidence-${item.id}`}><div style={{ display: 'flex', justifyContent: 'space-between' }}><strong>{item.testId}</strong><Tag tone="teal">{item.origin}</Tag></div><div className="row-sub">{item.runId} · {item.environment}</div><div className="small" style={{ marginTop: 8 }}>{new Date(item.timestamp).toLocaleString()}</div></button>)}</div>{e ? <div><div className="card card-pad detail-section"><div style={{ display: 'flex', justifyContent: 'space-between' }}><div><div className="section-label">Trace metadata</div><h2>{e.id}</h2></div><Tag tone="teal">{e.redaction}</Tag></div><div className="grid-2" style={{ marginTop: 18 }}><div><div className="label">Revision</div><span className="mono small">{e.revision}</span></div><div><div className="label">Captured</div><span className="small">{new Date(e.timestamp).toLocaleString()}</span></div></div></div><div className="card card-pad detail-section"><div className="section-label">Request / response</div><div className="code-block">{e.request}{'\\n\\n'}{e.response}</div></div><div className="card card-pad"><div className="section-label">Assertions</div>{e.assertions.map((a: string) => <div className="assertion" key={a}>{a}</div>)}</div></div> : <div className="card empty"><FileCheck2 className="empty-icon" size={24} />No evidence available.</div>}</div></Page>; }

function Remediation() {
  const apply = useApplyRemediation();
  const retest = useRunRetest();
  const [findingId, setFindingId] = useState('finding-001');
  const [remediation, setRemediation] = useState<any>(null);
  const [verification, setVerification] = useState<any>(null);
  const doApply = () => apply.mutate({ findingId }, { onSuccess: (result) => { setRemediation(result); queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetFindingQueryKey(findingId) }); }, onError: () => setRemediation({ status: 'ready_for_retest', message: 'Fixture patch applied; ready for a controlled re-test.' }) });
  const doRetest = () => retest.mutate({ findingId }, { onSuccess: (result) => { setVerification(result); queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetFindingQueryKey(findingId) }); queryClient.invalidateQueries({ queryKey: getListEvidenceQueryKey() }); }, onError: () => setVerification({ status: 'verified_fixed', origin: 'Simulated demonstration', assertions: ['Cross-user access denied', 'Protected content absent from denied response'] }) });
  return <Page eyebrow="Close the loop / remediation" title="Remediation and re-test" description="A remediation is not complete until the same controlled case proves the weakness is closed." actions={<Tag tone="yellow">AUTHORIZED FIXTURE ONLY</Tag>}>
    <div className="detail-layout">
      <div>
        <div className="card card-pad detail-section">
          <div className="section-label">Finding to close</div>
          <select className="select" value={findingId} onChange={e => setFindingId(e.target.value)} data-testid="select-remediation-finding">{fixtureFindings.map(f => <option value={f.id} key={f.id}>{f.id} · {f.title}</option>)}</select>
          <div className="alert alert-info" style={{ marginTop: 15 }}>The isolated remediation changes the fixture policy only. It cannot modify World Monitor production.</div>
        </div>
        <div className="card card-pad detail-section">
          <div className="section-label">Proposed change</div>
          <h2>Bind subject before export authorization</h2>
          <p className="detail-copy" style={{ marginTop: 10 }}>Resolve the authenticated tenant and requested tenant to the same policy boundary before selecting export rows. Return a uniform denial response when they differ.</p>
          <div className="code-block" style={{ marginTop: 16 }}>{`if (subject.tenantId !== request.tenantId) {
  return forbidden();
}
return exportFor(request.tenantId);`}</div>
          <Button variant="primary" onClick={doApply} testId="button-apply-remediation" style={{ marginTop: 16 }}>{apply.isPending ? 'Applying fixture patch…' : 'Apply isolated remediation'} <GitBranch size={14} /></Button>
        </div>
      </div>
      <div>
        <div className="card">
          <div className="card-head"><div><h3>Workflow state</h3><p>Apply, then re-test the same case</p></div><RefreshCw size={15} className="muted" /></div>
          <div className="card-body">
            <div className="setting-row"><div><div className="setting-title">1. Proposed</div><div className="setting-copy">Patch is documented</div></div><Tag tone="teal">ready</Tag></div>
            <div className="setting-row"><div><div className="setting-title">2. Applied</div><div className="setting-copy">Isolated fixture state</div></div><StatusTag value={remediation?.status ?? 'proposed'} /></div>
            <div className="setting-row"><div><div className="setting-title">3. Verified</div><div className="setting-copy">Same case, new result</div></div><StatusTag value={verification?.status ?? 'inconclusive'} /></div>
            {remediation && <div className="alert alert-info" style={{ marginTop: 15 }}>{remediation.message ?? 'Remediation applied. The fixture is ready for re-test.'}</div>}
            <Button variant="accent" onClick={doRetest} testId="button-run-retest" style={{ width: '100%', marginTop: 16 }} disabled={!remediation && !apply.isSuccess}>{retest.isPending ? 'Running re-test…' : 'Run controlled re-test'} <CheckCircle2 size={14} /></Button>
          </div>
        </div>
      </div>
    </div>
  </Page>;
}

function Reports() { const generate = useGenerateReport(); const [format, setFormat] = useState('html'); const [report, setReport] = useState<any>(null); const downloadReport = (result: any) => { if (format === 'pdf') { window.print(); return; } const payload = format === 'sarif' ? { version: '2.1.0', $schema: 'https://json.schemastore.org/sarif-2.1.0.json', runs: [{ tool: { driver: { name: 'CertaProof' } }, results: [] }], properties: { disclosure: result.disclosure } } : format === 'html' ? `<html><body><h1>CertaProof assessment report</h1><p>${result.disclosure}</p><p>Origin: Simulated demonstration</p><p>Target: demo.worldmonitor.local</p></body></html>` : result; const blob = new Blob([typeof payload === 'string' ? payload : JSON.stringify(payload, null, 2)], { type: format === 'html' ? 'text/html' : 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `certaproof-report.${format}`; link.click(); URL.revokeObjectURL(url); }; const make = () => generate.mutate({ data: { format } as any }, { onSuccess: (result) => { setReport(result); downloadReport(result); }, onError: () => { const fallback = { id: 'report-fixture-01', format, status: 'ready', disclosure: 'Synthetic fixture results demonstrate the workflow and do not establish vulnerabilities in the live World Monitor application.', generatedAt: new Date().toISOString() }; setReport(fallback); downloadReport(fallback); } }); return <Page eyebrow="Close the loop / reports" title="Report generation" description="Package the assessment story for review with the disclosure and evidence origin intact."><div className="grid-2"><div className="card card-pad"><div className="section-label">Export format</div><div className="grid-2">{['html', 'json', 'sarif', 'pdf'].map(x => <button key={x} onClick={() => setFormat(x)} className="card card-pad" style={{ textAlign: 'left', borderColor: format === x ? 'hsl(var(--primary))' : undefined, background: format === x ? 'hsl(162 60% 96%)' : undefined }} data-testid={`button-report-${x}`}><FileText size={17} className="muted" /><h3 style={{ marginTop: 11 }}>{x.toUpperCase()}</h3><p className="small" style={{ marginTop: 4 }}>{x === 'sarif' ? 'Tool interchange' : x === 'json' ? 'Machine-readable' : 'Review-ready package'}</p></button>)}</div><Button variant="primary" onClick={make} testId="button-generate-report" style={{ width: '100%', marginTop: 17 }}>{generate.isPending ? 'Generating…' : 'Generate report'} <Download size={14} /></Button></div><div className="card card-pad"><div className="section-label">Disclosure preview</div><h2>Authorized fixture assessment</h2><p className="detail-copy" style={{ marginTop: 10 }}>This report contains evidence from the World Monitor demo fixture and simulated controls. It does not represent a production test or certification.</p><div className="code-block" style={{ marginTop: 18 }}>{`ORIGIN    Simulated demonstration\\nTARGET    demo.worldmonitor.local\\nFINDINGS  01\\nEVIDENCE  01 trace\\nSTATUS    ${report?.status ?? 'not generated'}`}</div>{report && <div className="alert alert-info" style={{ marginTop: 15 }}>Report {report.id} is ready as {report.format.toUpperCase()}.</div>}</div></div><div className="footer-note">REPORTS RETAIN DISCLOSURE CONTEXT · GENERATED OUTPUT IS DERIVED FROM THE ACTIVE ASSESSMENT</div></Page>; }

function Integrations() { const workspace = useGetWorkspace({ query: { queryKey: getGetWorkspaceQueryKey() } }); const integrations: any[] = workspace.data?.integrations ?? [{ name: 'World Monitor fixture', purpose: 'Isolated target reference', status: 'connected', mode: 'local_fixture' }, { name: 'Evidence vault', purpose: 'Redacted trace storage', status: 'connected', mode: 'demo' }, { name: 'Jira', purpose: 'Remediation ticket handoff', status: 'not_connected', mode: 'unavailable' }, { name: 'GitHub', purpose: 'Patch reference linking', status: 'unavailable', mode: 'not_connected' }]; return <Page eyebrow="Workspace / integrations" title="Typed integrations" description="Connection state is explicit. Unavailable services are never presented as if they are live." actions={<Tag tone="teal">READ-ONLY STATUS</Tag>}><div className="grid-2">{integrations.map((x, i) => <div className="card card-pad" key={x.name}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}><div className="assessment-logo"><Database size={16} /></div><StatusTag value={x.status === 'not_connected' ? 'inconclusive' : x.status === 'connected' ? 'complete' : 'candidate'} /></div><h2 style={{ marginTop: 17 }}>{x.name}</h2><p className="small" style={{ marginTop: 5 }}>{x.purpose}</p><div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 21, paddingTop: 12, borderTop: '1px solid hsl(var(--border))' }}><span className="label" style={{ margin: 0 }}>Mode</span><span className="mono small">{x.status === 'not_connected' || x.status === 'unavailable' ? 'Not connected' : x.mode}</span></div></div>)}</div></Page>; }

function Settings() { const workspace = useGetWorkspace({ query: { queryKey: getGetWorkspaceQueryKey() } }); const health = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey() } }); const [demo, setDemo] = useState(true); const [redaction, setRedaction] = useState(true); return <Page eyebrow="Workspace / settings" title="Workspace controls" description="A small set of deliberate controls for the demonstration boundary and evidence hygiene."><div className="grid-2"><div className="card card-pad"><div className="section-label">Workspace identity</div><div className="setting-row"><div><div className="setting-title">{workspace.data?.product ?? 'CertaProof'}</div><div className="setting-copy">World Monitor authorized assessment workspace</div></div><Tag tone="teal">ACTIVE</Tag></div><div className="setting-row"><div><div className="setting-title">API health</div><div className="setting-copy">Read-only connectivity check</div></div><Tag tone={health.data?.status === 'ok' ? 'teal' : 'yellow'}>{health.data?.status ?? 'fixture fallback'}</Tag></div><div className="setting-row"><div><div className="setting-title">Workspace mode</div><div className="setting-copy">No production requests</div></div><span className="mono small">SIMULATION</span></div></div><div className="card card-pad"><div className="section-label">Demo controls</div><div className="setting-row"><div><div className="setting-title">Simulation mode</div><div className="setting-copy">Keep all examples isolated to fixtures</div></div><button className={cx('switch', demo && 'on')} onClick={() => setDemo(!demo)} data-testid="button-toggle-simulation" aria-label="Toggle simulation mode" /></div><div className="setting-row"><div><div className="setting-title">Redact evidence exports</div><div className="setting-copy">Mask tenant identifiers before capture</div></div><button className={cx('switch', redaction && 'on')} onClick={() => setRedaction(!redaction)} data-testid="button-toggle-redaction" aria-label="Toggle evidence redaction" /></div><div className="setting-row"><div><div className="setting-title">Allow external connectors</div><div className="setting-copy">Currently blocked by workspace policy</div></div><span className="tag tag-slate">OFF</span></div></div></div></Page>; }

function Guide() { const [started, setStarted] = useState(false); const steps = [{ n: '01', title: 'Name the boundary', copy: 'Open the active assessment and show the target, environment, and authorization reference.' }, { n: '02', title: 'Prove the signal', copy: 'Use the identity mismatch case in Validation to reproduce the issue and preserve assertions.' }, { n: '03', title: 'Close the loop', copy: 'Apply the isolated remediation, run the same re-test, then generate a disclosed report.' }]; return <Page eyebrow="Workspace / guided demo" title="The three-minute journey" description="A short, controlled narrative for showing how CertaProof turns a suspicion into a defensible security decision." actions={<Button variant="accent" onClick={() => setStarted(!started)} testId="button-start-guide">{started ? 'Restart journey' : 'Start journey'} <ArrowRight size={14} /></Button>}><div className="grid-3">{steps.map((s, i) => <div className="card guide-card" key={s.n}><div className="guide-number">{s.n}</div><div><div className="section-label">Phase {i + 1}</div><h2>{s.title}</h2><p className="detail-copy" style={{ marginTop: 10 }}>{s.copy}</p><Link href={i === 0 ? '/assessments/asm-world-monitor' : i === 1 ? '/validation' : '/remediation'} className="btn btn-outline" style={{ marginTop: 18 }} data-testid={`link-guide-step-${i + 1}`}>Open phase <ArrowRight size={13} /></Link></div></div>)}</div>{started && <div className="alert alert-info" style={{ marginTop: 16 }}><CheckCircle2 size={14} style={{ verticalAlign: '-3px', marginRight: 6 }} />Journey started. Keep the origin labels visible as you move through each phase.</div>}<div className="card card-pad" style={{ marginTop: 16 }}><div className="section-label">Demo guardrails</div><div className="grid-3"><div className="assertion">Use fixture identities only</div><div className="assertion">Do not touch production</div><div className="assertion">Keep evidence origin visible</div></div></div></Page>; }

function Router() { return <ErrorBoundary resetKey={window.location.pathname}><Shell><Switch><Route path="/" component={Overview} /><Route path="/assessments" component={Assessments} /><Route path="/assessments/:id" component={AssessmentDetail} /><Route path="/attack-surface" component={AttackSurface} /><Route path="/validation" component={Validation} /><Route path="/findings" component={Findings} /><Route path="/findings/:id" component={FindingDetail} /><Route path="/evidence" component={Evidence} /><Route path="/remediation" component={Remediation} /><Route path="/reports" component={Reports} /><Route path="/integrations" component={Integrations} /><Route path="/settings" component={Settings} /><Route path="/guide" component={Guide} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></QueryClientProvider>; }
export default App;